def largest_free_square(plan):
    best = 0
    above = [0] * len(plan[0])
    for row in plan:
        cur = [0] * len(row)
        for c, ch in enumerate(row):
            if ch == '.':
                if c == 0:
                    cur[c] = 1
                else:
                    cur[c] = 1 + min(above[c], cur[c - 1], above[c - 1])
                best = max(best, cur[c])
        above = cur
    return best
